def write(path, value):
    with Path(path).open('x') as out:
        json.dump(value, out, indent=2, sort_keys=True)
        out.write('\n')


def no_injected_options():
    assert not any(name in os.environ for name in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS'))


def sources():
    return {str(path): sha(path) for path in [Path(__file__), HERE / 'build_overlay_source.py',
        HERE / 'protocol.md', HERE / 'discover_publication_targets.py', OLD / 'run-comparison.py',
        OLD / 'runtime_identity.py', HERE / 'helper-src' / HELPER]}


def class_bytes(classpath, name):
    """Read the first actual definition, respecting the classpath's overlay order."""
    for entry in classpath.split(os.pathsep):
        path = Path(entry)
        if path.is_dir():
            candidate = path / name
            if candidate.is_file():
                return candidate.read_bytes(), str(candidate)
        elif zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as archive:
                if name in archive.namelist():
                    return archive.read(name), str(path) + '!/' + name
    raise AssertionError('Selected base class missing: ' + name)


def class_abi(data):
    """Field/method descriptors and access flags, independent of debug/source line attributes."""
    offset = 0

    def read(fmt):
        nonlocal offset
        size = struct.calcsize(fmt)
        result = struct.unpack_from(fmt, data, offset)
        offset += size
        return result[0] if len(result) == 1 else result

    assert read('>I') == 0xCAFEBABE
    minor, major = read('>HH')
    pool = [None] * read('>H')
    index = 1
    while index < len(pool):
        tag = read('>B')
        if tag == 1:
            size = read('>H')
            pool[index] = data[offset:offset + size].decode('utf-8')
            offset += size
        elif tag in (7, 8, 16, 19, 20):
            pool[index] = read('>H')
        elif tag in (3, 4, 9, 10, 11, 12, 17, 18):
            offset += 4
        elif tag in (5, 6):
            offset += 8
            index += 1
        elif tag == 15:
            offset += 3
        else:
            raise AssertionError('Unknown classfile constant tag: ' + str(tag))
        index += 1
    access, name, superclass = read('>HHH')
    interfaces = [pool[pool[read('>H')]] for _ in range(read('>H'))]

    def members():
        nonlocal offset
        result = []
        for _ in range(read('>H')):
            flags, member_name, descriptor = read('>HHH')
            result.append([flags, pool[member_name], pool[descriptor]])
            for _ in range(read('>H')):
                read('>H')
                size = read('>I')
                offset += size
        return sorted(result, key=lambda member: (member[1], member[2]))

    return {'major': major, 'minor': minor, 'access': access, 'name': pool[pool[name]],
        'superclass': pool[pool[superclass]], 'interfaces': interfaces, 'fields': members(), 'methods': members()}


def verify_descriptor_inputs(descriptor):
    for name, value in descriptor.items():
        if not name.endswith('File'):
            continue
        digest = descriptor.get(name + 'Sha256', descriptor.get(name[:-4] + 'Sha256'))
        if digest is not None:
            assert sha(Path(value)) == digest, 'Changed selected runtime input: ' + name


def compile_overlay(args):
    no_injected_options()
    folder = args.generated.resolve(strict=True)
    assert folder.is_relative_to(HERE)
    generation = json.loads((folder / 'source-generation.json').read_text())
    assert generation['sourceSha256'] == sha(folder / 'preimage' / REL)
    assert generation['generatedSourceSha256'] == sha(folder / 'src' / REL)
    assert generation['helperSha256'] == sha(folder / 'src' / HELPER)
    descriptor_file = args.base_runtime.resolve(strict=True)
    descriptor = json.loads(descriptor_file.read_text())
    verify_descriptor_inputs(descriptor)
    classpath = Path(descriptor['classpathFile']).read_text().strip()
    manifest = identity.classpath_manifest(classpath)
    assert manifest == json.loads(Path(descriptor['classpathManifestFile']).read_text())
    if generation['maskGuardPresent']:
        overlay_source = Path(descriptor['overlaySourceFile']).resolve(strict=True)
        overlay_hash = descriptor.get('overlaySourceFileSha256', descriptor.get('overlaySourceSha256'))
        assert overlay_hash and sha(overlay_source) == overlay_hash == generation['sourceSha256'], \
            'Masked diagnostic preimage differs from the selected experimental runtime source'
        source_binding = {'role': 'experimental masked runtime source', 'file': str(overlay_source), 'sha256': overlay_hash}
    else:
        _, original_manifest = identity.original_identity()
        assert len(manifest) == 128 and manifest[1:] == original_manifest, 'Original diagnostic needs exact common runtime'
        assert generation['sourceSha256'] == ORIGINAL_SOURCE_SHA, 'Original materializer preimage changed'
        source_binding = {'role': 'preserved original source and exact common runtime', 'sha256': ORIGINAL_SOURCE_SHA}
    raw, selected = folder / 'compiled-output', folder / 'classes'
    raw.mkdir(exist_ok=False)
    selected.mkdir(exist_ok=False)
    argv = [str(Path(JAVA).with_name('javac')), '-proc:none', '-implicit:none', '-encoding', 'UTF-8',
        '--release', '25', '-cp', classpath, '-sourcepath', '', '-d', str(raw)]
    argv += [str(p) for p in sorted((folder / 'src').rglob('*.java'))]
    write(folder / 'compile-command.json', {'argv': argv, 'cwd': str(ROOT), 'startedEpochNs': time.time_ns()})
    with (folder / 'compile.log').open('xb') as log:
        result = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=60)
    write(folder / 'compile-result.json', {'exitCode': result.returncode, 'finishedEpochNs': time.time_ns()})
    assert result.returncode == 0, 'Preserved failed diagnostic compile'
    emitted = identity.tree_files(raw)
    changed = {str(REL.with_suffix('.class')), str(HELPER.with_suffix('.class'))}
    kept = {str(REL.parent / name) for name in ('NativeResultMaterializerPlan.class',
        'NativeResultMaterializer$FactorMemo.class', 'NativeResultMaterializer$FactorPage.class')}
    assert set(emitted) == changed | kept, set(emitted)
    abi_checks = {}
    for name in sorted(kept):
        frozen_bytes, frozen_path = class_bytes(classpath, name)
        emitted_abi = class_abi((raw / name).read_bytes())
        selected_abi = class_abi(frozen_bytes)
        assert emitted_abi == selected_abi, 'Discarded compiled class is not ABI-compatible: ' + name
        abi_checks[name] = {'selectedClass': frozen_path,
            'selectedClassSha256': __import__('hashlib').sha256(frozen_bytes).hexdigest(),
            'emittedClassSha256': emitted[name]['sha256'], 'matchingABI': emitted_abi}
    for name in changed:
        target = selected / name
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(raw / name, target)
    cp = str(selected) + os.pathsep + classpath
    composed = identity.classpath_manifest(cp)
    assert composed[1:] == manifest
    (folder / 'classpath.txt').write_text(cp + '\n')
    write(folder / 'classpath-manifest.json', composed)
    source_id = descriptor['sourceIdentity'] + '+publication-diagnostic-sha256-' + generation['generatedSourceSha256']
    write(folder / 'runtime.json', {'format': 1, 'diagnosticOnly': True, 'sourceIdentity': source_id,
        'baseRuntimeDescriptor': str(descriptor_file), 'baseRuntimeDescriptorSha256': sha(descriptor_file),
        'baseManifest': manifest, 'baseSourceIdentity': descriptor['sourceIdentity'],
        'sourceGenerationFile': str(folder / 'source-generation.json'),
        'sourceGenerationSha256': sha(folder / 'source-generation.json'),
        'classpathFile': str(folder / 'classpath.txt'), 'classpathFileSha256': sha(folder / 'classpath.txt'),
        'classpathManifestFile': str(folder / 'classpath-manifest.json'),
        'classpathManifestSha256': sha(folder / 'classpath-manifest.json'),
        'manifest': composed, 'rawJavacOutput': emitted, 'overlayClasses': sorted(changed),
        'frozenClassesKept': sorted(kept), 'maskGuardPresent': generation['maskGuardPresent'],
        'frozenClassABIChecks': abi_checks, 'selectedSourceBinding': source_binding, 'extraWeakDereferences': 0})
    print(json.dumps({'runtime': str(folder / 'runtime.json'), 'benchmarkJvms': 0}), flush=True)


def read_runtime(path):
    runtime = json.loads(Path(path).read_text())
    assert runtime['diagnosticOnly'] and runtime['extraWeakDereferences'] == 0
    assert sha(runtime['baseRuntimeDescriptor']) == runtime['baseRuntimeDescriptorSha256']
    assert sha(runtime['sourceGenerationFile']) == runtime['sourceGenerationSha256']
    assert sha(runtime['classpathFile']) == runtime['classpathFileSha256']
    assert sha(runtime['classpathManifestFile']) == runtime['classpathManifestSha256']
    cp = Path(runtime['classpathFile']).read_text().strip()
    assert identity.classpath_manifest(cp) == runtime['manifest']
    return runtime, cp


def prepare(args):
    no_injected_options()
    runtime_path = args.runtime.resolve(strict=True)
    runtime, _ = read_runtime(runtime_path)
    assert not args.mask or runtime['maskGuardPresent'], 'Cannot omit targets without actual guard'
    folder = HERE / 'suites' / args.name
    folder.mkdir(parents=True, exist_ok=False)
    fixtures = {name: base.FIXTURES[name] for name in args.fixtures}
    plan = {'format': 1, 'name': args.name, 'sources': sources(), 'runtime': str(runtime_path),
        'runtimeSha256': sha(runtime_path), 'sourceIdentity': runtime['sourceIdentity'],
        'fixtures': fixtures, 'mask': args.mask, 'queryLimitBytes': args.query_limit,
        'globalLimitBytes': 1_073_741_824, 'java': JAVA, 'jvmArguments': JVM, 'warmup': 3, 'iterations': 1,
        'consumption': 'full', 'transport': 'dense', 'timeoutSeconds': 300,
        'purpose': 'Counter, ownership, route and canonical-page attribution only; durations and allocations excluded',
        'failurePolicy': 'Preserve failures and all raw files; no replacement runs',
        'createdEpochNs': time.time_ns()}
    write(folder / 'protocol.json', plan)
    print(json.dumps({'protocol': str(folder / 'protocol.json'), 'sha256': sha(folder / 'protocol.json')}))


def load_plan(name):
    no_injected_options()
    folder = HERE / 'suites' / name
    plan = json.loads((folder / 'protocol.json').read_text())
    assert plan['sources'] == sources(), 'Frozen diagnostic source changed'
    assert plan['name'] == name and plan['java'] == JAVA and plan['jvmArguments'] == JVM
    assert plan['warmup'] == 3 and plan['iterations'] == 1 and plan['consumption'] == 'full'
    assert plan['runtimeSha256'] == sha(plan['runtime'])
    runtime, cp = read_runtime(plan['runtime'])
    return folder, plan, runtime, cp


def owner_analysis(path):
    records = [json.loads(line) for line in path.read_text().splitlines()]
    header = records[0]
    targets = [r for r in records[1:] if r['type'] == 'target']
    pages = [r for r in records[1:] if r['type'] == 'page']
    assert len(records) == 1 + len(targets) + len(pages)
    counts, claims, occupied = Counter(), Counter(), Counter()
    keys = set()
    for page in pages:
        key = tuple(page[name] for name in ('target', 'namespace', 'group', 'parent', 'column', 'pageIndex'))
        assert key not in keys
        keys.add(key)
        assert 0 <= page['occupied'] <= 64 and int(page['occupiedMask']).bit_count() == page['occupied']
        assert page['claim'] == 16_384
        counts[page['target']] += 1
        claims[page['target']] += page['claim']
        occupied[page['target']] += page['occupied']
    checks = {'pageCount': header['pageCount'] == len(pages), 'noExtraWeakDereferences': header['extraWeakDereferences'] == 0}
    for target in targets:
        index = target['target']
        assert target['canonical'] in range(len(targets))
        checks[f'{index}:findPartition'] = target['find'] == sum(target[k] for k in (
            'ordinaryIdMiss', 'ordinaryHit', 'ordinaryWeakMiss', 'ordinaryWitnessMiss'))
        checks[f'{index}:ordinaryMissToFactor'] = target['factorLookup'] == target['find'] - target['ordinaryHit']
        checks[f'{index}:factorPartition'] = target['factorLookup'] == sum(target[k] for k in (
            'factorInitialMiss', 'factorPageMiss', 'factorCellMiss', 'factorWeakMiss', 'factorWitnessMiss', 'factorHit'))
        checks[f'{index}:publicationPartition'] = target['publicationCall'] == sum(target[k] for k in (
            'publicationInitialMiss', 'publicationOwnerMiss', 'publicationPageMiss', 'publicationComplete', 'publicationSkipped'))
        checks[f'{index}:admissionPartition'] = target['pageAttempt'] == target['pageAdmitted'] + target['pageRefused']
        checks[f'{index}:allPagesReleased'] = target['pageAdmitted'] == target['pagesReleased']
        checks[f'{index}:allGrantedBytesReleased'] = target['pageBytesGranted'] == target['pageBytesReleased']
        target.update({'finalPages': counts[index], 'finalPageBytes': claims[index], 'finalOccupiedCells': occupied[index]})
    return {'path': str(path), 'sha256': sha(path), 'header': header, 'targets': targets,
        'checks': checks, 'valid': all(checks.values()), 'pageBytes': sum(claims.values())}


def validate_run(folder, plan, fixture, jvm):
    records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
    metadata, queries = records[0], records[1:]
    assert len(queries) == 4
    expected = {**fixture['metadata'], 'source': plan['sourceIdentity'], 'arm': plan['name'],
        'jvmArguments': jvm, 'consumption': 'full', 'nativeEvaluation': True, 'directAdjacency': True,
        'directAdjacencyMode': 'PREFER', 'valueOverlay': False, 'forceSync': False,
        'globalLedgerLimitBytes': plan['globalLimitBytes'], 'perQueryLedgerLimitBytes': plan['queryLimitBytes'],
        'indexes': 'spoc,ospc,psoc,posc', 'warmup': 3, 'measurementsToRun': 1}
    checks = {'metadata:' + key: metadata.get(key) == value for key, value in expected.items()}
    setup = metadata['adjacencySetup']
    checks['adjacencySetup'] = setup['state'] == 'ACTIVE' and setup['currentRevisionReady']
    owners = [owner_analysis(path) for path in sorted((folder / 'page-records').glob('owner-*.jsonl'),
        key=lambda path: int(path.stem.split('-')[1]))]
    checks['oneOwnerPerQuery'] = len(owners) == len(queries)
    for i, sample in enumerate(queries):
        counters, adjacency = sample['counters'], sample['adjacency']
        checks[f'query{i}:chronology'] = sample['iteration'] == i - 3 and sample['stage'] == ('warmup' if i < 3 else 'measurement')
        checks[f'query{i}:result'] = all(sample[key] for key in ('valid', 'complete', 'rowCountValid', 'checksumValid')) \
            and sample['rows'] == fixture['metadata']['expectedRows'] \
            and sample['checksum'] == fixture['metadata']['expectedChecksum']
        if fixture['metadata']['fixture'] == 'coherent-two-optional-tail-tuples':
            checks[f'query{i}:exactBag'] = sample['exactBagValid'] and sample['partialMembershipValid']
        checks[f'query{i}:ledger'] = sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 and sample['ledgerReleased']
        checks[f'query{i}:normalAUTO'] = sample['autoRequested'] and sample['auto'] \
            and bool(sample['successfulSelections']) and not any('forced' in r['mode'] for r in sample['successfulSelections'])
        checks[f'query{i}:nativeIR'] = counters['semanticNativeCompiles'] == counters['irOpened'] == 1 \
            and counters['irRows'] == fixture['metadata']['expectedRows']
        checks[f'query{i}:coordinateOwner'] = counters['coordinateAdmissions']['opened'] == 1 \
            and counters['coordinateAdmissions']['initialAdmissionRefused'] == counters['coordinateAdmissions']['growthAdmissionRefused'] == 0
        checks[f'query{i}:compiledMeasurement'] = i < 3 or counters['compiledBinds'] == 1 \
            and counters['interpretedBinds'] == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0
        checks[f'query{i}:adjacency'] = adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE' \
            and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore'] \
            == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter'] == setup['currentDataRevision'] \
            and adjacency['lookupHits'] > 0
        if i < len(owners):
            owner_targets = owners[i]['targets']
            names_match = [target['name'] for target in owner_targets] == metadata['projectedNames']
            identity_aliases = all(target['target'] == target['canonical'] == index
                for index, target in enumerate(owner_targets))
            checks[f'query{i}:projectedNames'] = names_match
            checks[f'query{i}:noAliases'] = identity_aliases
            checks[f'query{i}:fullyBoundReads'] = sample['bindingReads'] == sample['rows'] * metadata['width']
            eligible = names_match and identity_aliases and checks[f'query{i}:fullyBoundReads']
            checks[f'query{i}:findReconciliation'] = eligible \
                and sum(target['find'] for target in owner_targets) == sample['bindingReads']
            checks[f'query{i}:hitResolverReconciliation'] = eligible \
                and sum(target['ordinaryHit'] + target['factorHit'] for target in owner_targets) \
                    + counters['lazyValueCalls'] == sample['bindingReads']
            checks[f'query{i}:rememberResolverReconciliation'] = eligible \
                and sum(target['rememberCall'] for target in owner_targets) == counters['lazyValueCalls']
            owners[i]['query'] = {key: sample[key] for key in ('stage', 'iteration', 'rows', 'checksum',
                'ledgerBeforeBytes', 'ledgerPeakBytes', 'ledgerAfterBytes', 'successfulSelections', 'counters', 'adjacency')}
            checks[f'query{i}:ownerCounters'] = owners[i]['valid'] and owners[i]['header']['owner'] == i + 1
            checks[f'query{i}:ownerQueryLimit'] = owners[i]['header']['queryLimit'] == plan['queryLimitBytes']
    audit = json.loads((folder / 'root-host-audit.json').read_text())
    checks['rootAudit'] = audit['harnessReturned'] and audit['harnessFailureClass'] is None \
        and audit['hostedGenericTotal'] == 0 and audit['semanticNativeCompilesTotal'] == 4 \
        and audit['harnessMain'] == fixture['harnessMain'] and audit['readPhase'] == fixture['rootReadPhase']
    analysis = {'format': 1, 'valid': all(checks.values()), 'checks': checks, 'owners': owners,
        'metadata': metadata, 'rootAudit': audit, 'performanceInference': False,
        'releaseCoverage': 'Page grants/releases are explicitly counted. Ordinary/directory/memo claims are close-time '
            'snapshots only; the harness separately proves final zero query-ledger endpoints.'}
    write(folder / 'analysis.json', analysis)
    assert analysis['valid'], 'Preserved failed diagnostic validation: ' + str(folder)
    return analysis


def run(args):
    folder, plan, runtime, cp = load_plan(args.name)
    runs = folder / 'runs'
    runs.mkdir(exist_ok=False)
    results = {}
    for name, fixture in plan['fixtures'].items():
        target = runs / name
        target.mkdir()
        pages = target / 'page-records'
        pages.mkdir()
        jvm = JVM + ['-D' + OUTPUT + '=' + str(pages), '-D' + LIMIT + '=' + str(plan['queryLimitBytes']),
            '-D' + base.PROPERTY + '=dense']
        if runtime['maskGuardPresent']:
            jvm += ['-D' + MASK + '=' + plan['mask']]
        argv = [JAVA] + jvm + ['-cp', cp, fixture['launcher'], '--arm=' + plan['name'],
            '--source=' + plan['sourceIdentity']] + fixture['arguments'] + ['--warmup=3', '--iterations=1',
            '--consumption=full', '--store=' + str(target / 'store'), '--output=' + str(target / 'samples.jsonl')]
        write(target / 'command.json', {'argv': argv, 'cwd': str(ROOT), 'startedEpochNs': time.time_ns(),
            'protocolSha256': sha(folder / 'protocol.json'), 'runtimeSha256': plan['runtimeSha256']})
        with (target / 'console.log').open('xb') as log:
            try:
                process = subprocess.run(argv, cwd=ROOT, stdout=log, stderr=subprocess.STDOUT, timeout=plan['timeoutSeconds'])
            except subprocess.TimeoutExpired:
                write(target / 'process-result.json', {'exitCode': None, 'timedOut': True, 'finishedEpochNs': time.time_ns()})
                raise
        write(target / 'process-result.json', {'exitCode': process.returncode, 'finishedEpochNs': time.time_ns()})
        assert process.returncode == 0, 'Preserved failed diagnostic process'
        result = validate_run(target, plan, fixture, jvm)
        results[name] = {'analysis': str(target / 'analysis.json'), 'analysisSha256': sha(target / 'analysis.json'),
            'valid': result['valid'], 'lastOwner': result['owners'][-1]}
        print(json.dumps({'fixture': name, 'valid': True, 'performanceInference': False,
            'targets': [{key: t[key] for key in ('name', 'ordinaryHit', 'factorHit', 'publicationCall',
                'publicationSkipped', 'publicationWrite', 'finalPages', 'finalPageBytes')}
                for t in result['owners'][-1]['targets']]}), flush=True)
    write(folder / 'analysis.json', {'format': 1, 'valid': all(r['valid'] for r in results.values()),
        'protocolSha256': sha(folder / 'protocol.json'), 'fixtures': results, 'performanceInference': False})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('action', choices=['compile', 'prepare', 'run'])
    parser.add_argument('--generated', type=Path, default=HERE / 'generated/original')
    parser.add_argument('--base-runtime', type=Path, default=OLD / 'compiled-v1/runtime-descriptor.json')
    parser.add_argument('--runtime', type=Path, default=HERE / 'generated/original/runtime.json')
    parser.add_argument('--name')
    parser.add_argument('--mask', default='')
    parser.add_argument('--query-limit', type=int, default=536_870_912)
    parser.add_argument('--fixtures', nargs='+', choices=list(base.FIXTURES), default=list(base.FIXTURES))
    parser.add_argument('--slot-granted', action='store_true')
    args = parser.parse_args()
    if args.action in ('compile', 'run'):
        assert args.slot_granted, 'Java execution requires coordinator exclusive slot'
    if args.action == 'compile':
        compile_overlay(args)
    elif args.action == 'prepare':
        assert args.name
        prepare(args)
    else:
        assert args.name
        run(args)


if __name__ == '__main__':
    main()
